import{_ as e,o as l,c as r,a2 as h}from"./chunks/framework.BXzK3EA4.js";const c=JSON.parse('{"title":"사회 서사 배치 B040","description":"","frontmatter":{},"headers":[],"relativePath":"world/Story-Batch-B040.md","filePath":"world/Story-Batch-B040.md"}'),i={name:"world/Story-Batch-B040.md"};function t(o,a,p,d,n,u){return l(),r("div",null,[...a[0]||(a[0]=[h('<h1 id="사회-서사-배치-b040" tabindex="-1">사회 서사 배치 B040 <a class="header-anchor" href="#사회-서사-배치-b040" aria-label="Permalink to &quot;사회 서사 배치 B040&quot;">​</a></h1><p>이 페이지는 World-Narrative-Atlas의 읽기 전용 투영물입니다.</p><ul><li>원본 앵커: <code>docs/game-logic/World-Narrative-Atlas.md</code></li><li>원본 해시: <code>61650e2e4605df4e147030b08457d51d0a9366362fe6599d89ff6505683708e1</code></li></ul><h2 id="인물-k370-·-초태온" tabindex="-1">인물 K370 · 초태온 <a class="header-anchor" href="#인물-k370-·-초태온" aria-label="Permalink to &quot;인물 K370 · 초태온&quot;">​</a></h2><ul><li>연결: house=HP07 theater=XT01 scenarios=XT01-SC3,STORY-B040-K370</li></ul><h3 id="정체성·출신" tabindex="-1">정체성·출신 <a class="header-anchor" href="#정체성·출신" aria-label="Permalink to &quot;정체성·출신&quot;">​</a></h3><p>초태온은 아차 교량 초소에서 호송칸 통과 시각을 봉인 시각보다 먼저 적는 아차구의관문국(S14) 약소국 회의 관문 증인이다.</p><p>구두 합의를 통행증으로 바꾸려는 사신이 날짜를 고치려 하면 스탬프 함을 발밑으로 끌어당긴다.</p><h3 id="붕괴-전-삶" tabindex="-1">붕괴 전 삶 <a class="header-anchor" href="#붕괴-전-삶" aria-label="Permalink to &quot;붕괴 전 삶&quot;">​</a></h3><p>관문 견습 때 그는 회의장 전갈과 교량 전갈을 같은 시각에 두 장으로 남기는 연습만 반복했다.</p><p>증인 없는 매수 소문은 원장 난외에도 올리지 않는 손이 굳어, 위조 통과증 한 장을 창구 물건처럼 취급하는 버릇을 적의 습관으로 불렀다.</p><h3 id="가문·기업·공동체" tabindex="-1">가문·기업·공동체 <a class="header-anchor" href="#가문·기업·공동체" aria-label="Permalink to &quot;가문·기업·공동체&quot;">​</a></h3><p>한강교량공회(HP07) 관문 배석에 이름이 있으나 공동헌장 사본의 봉인 끈이 확인되기 전에는 강국별 분할 쪽지 칸을 열지 않는다.</p><p>정유라의 공동교섭 호송이 늦어도 장세화의 상호호송 초안은 회의 시작 벨 전에만 펼친다.</p><h3 id="붕괴의-상처" tabindex="-1">붕괴의 상처 <a class="header-anchor" href="#붕괴의-상처" aria-label="Permalink to &quot;붕괴의 상처&quot;">​</a></h3><p>열한 자리 회의 호송이 교량에 닿던 아침, 분할 복속 쪽지가 든 상자가 공동헌장 철과 같은 칸에 실려 있었다.</p><p>초태온은 상자 바퀴를 난간에 붙인 채 헌장 철만 스탬프 아래로 밀었고, 범람멧돼지군(G01)이 교량 하부 진흙을 파헤치던 순간 위조 통과증이 증인석 의자 밑에 미끄러져 들어왔다.</p><h3 id="생존-전환점" tabindex="-1">생존 전환점 <a class="header-anchor" href="#생존-전환점" aria-label="Permalink to &quot;생존 전환점&quot;">​</a></h3><p>통과 전갈을 관문 벽과 회의장 칠판에 같은 분으로 붙이면서 쪽지 상자의 단독 통과가 끊겼다.</p><p>근주하의 서명 원장 시각이 맞자 초태온은 XT01-SC3 아차 봉인 키 분할 번호를 전갈 상단에 박았고, 장세화 초안 문장은 회의 벨이 울린 뒤 접어 주머니에 넣었다.</p><h3 id="현재-지위" tabindex="-1">현재 지위 <a class="header-anchor" href="#현재-지위" aria-label="Permalink to &quot;현재 지위&quot;">​</a></h3><p>아차 교량 초소에서 초태온은 난간 녹물 길이로 대기 호송 수를 가늠한다.</p><p>날짜를 고치는 손이 보이면 스탬프 함 뚜껑을 발로 닫는다.</p><p>교량공회 심부름이 분할 쪽지 우선 통과를 요구해도 그는 공동헌장 끈이 마른 뒤에만 칸을 연다.</p><h3 id="비밀·빚·죄책감" tabindex="-1">비밀·빚·죄책감 <a class="header-anchor" href="#비밀·빚·죄책감" aria-label="Permalink to &quot;비밀·빚·죄책감&quot;">​</a></h3><p>의자 밑 위조 통과증을 바로 찢지 못하고 교대 끝까지 구두코로 눌러 둔 적이 있다.</p><p>눌린 모서리 길이를 그는 전갈 용지 귀퉁이 접힘으로만 기억하고, 증인석에 앉을 때마다 그 접힘을 엄지로 편다.</p><h3 id="관계-공동과거" tabindex="-1">관계 공동과거 <a class="header-anchor" href="#관계-공동과거" aria-label="Permalink to &quot;관계 공동과거&quot;">​</a></h3><p>정유라가 호송 가방 봉인 끈을 보여 주면 초태온은 공동헌장 철 쪽수만 소리 내어 맞춘다.</p><p>근주하가 서명 원장 시각을 손가락으로 가리킬 때 둘은 전갈 상단 숫자만 나란히 읽고, 장세화의 상호호송 초안이 젖어 도착하면 초태온은 벨이 울리기 전에 초안을 접어 안주머니로 내린다.</p><h3 id="_3막-개인-서사선" tabindex="-1">3막 개인 서사선 <a class="header-anchor" href="#_3막-개인-서사선" aria-label="Permalink to &quot;3막 개인 서사선&quot;">​</a></h3><p>쪽지 상자가 난간에 멈춘 뒤 통과 전갈이 두 장소에 동시에 붙고, 봉인 키 분할 번호가 상단에 고정된다.</p><p>초태온이 마지막에 고르는 수는 분할 호송칸을 원장에서 지우는 쪽과 광물 검사 칸 하나를 강국 측에 내주는 쪽으로 갈린다.</p><h3 id="분기-결말" tabindex="-1">분기 결말 <a class="header-anchor" href="#분기-결말" aria-label="Permalink to &quot;분기 결말&quot;">​</a></h3><p>공개 쪽에서 초태온은 공동헌장 사본만 관문 원장 필수 통과물로 올리고 분할 복속 쪽지 호송칸을 삭제한다.</p><p>거래 쪽에서 광물 샘플 검사 한 칸을 강국 호송대에 내주며 봉인 키 조각 하나를 회의 당번에게 맡기고, 통과 시각 공개는 정유라 호송 가방 끈 일련과 맞춘다.</p><p>아차 교량 초소의 통과 시각 공개 권한은 두 수 모두에서 거둬지지 않는다.</p><h3 id="_3막" tabindex="-1">3막 <a class="header-anchor" href="#_3막" aria-label="Permalink to &quot;3막&quot;">​</a></h3><ul><li>1막: 분할 쪽지 상자 난간 정지와 공동헌장 단독 통과</li><li>2막: 이중 전갈 동시 부착과 봉인 키 분할 번호 고정</li><li>3막: 쪽지 호송칸 말소 대 광물 검사칸·키 조각 위탁</li></ul><h3 id="분기-결말-목록" tabindex="-1">분기 결말 목록 <a class="header-anchor" href="#분기-결말-목록" aria-label="Permalink to &quot;분기 결말 목록&quot;">​</a></h3><ul><li>K370-OUT-A: 공동헌장 필수 통과·분할 쪽지 호송칸 삭제</li><li>K370-OUT-B: 광물 검사칸 양보·봉인 키 조각 위탁·호송 끈 연동 시각</li></ul><h2 id="인물-k395-·-초시람" tabindex="-1">인물 K395 · 초시람 <a class="header-anchor" href="#인물-k395-·-초시람" aria-label="Permalink to &quot;인물 K395 · 초시람&quot;">​</a></h2><ul><li>연결: house=HP08 theater=XT03 scenarios=XT03-SC2,STORY-B040-K395</li></ul><h3 id="정체성·출신-1" tabindex="-1">정체성·출신 <a class="header-anchor" href="#정체성·출신-1" aria-label="Permalink to &quot;정체성·출신&quot;">​</a></h3><p>초시람은 가락 경매대 앞에서 패들 손잡이의 땀 자국으로 친위 낙찰을 가리는 가락잠실배급국(S15) 공신 보상 경매 당사자다.</p><p>시작가가 지워진 번호가 자기 이름 옆에 붙으면 자리를 뜨지 않고 분필 가루만 손등으로 닦는다.</p><h3 id="붕괴-전-삶-1" tabindex="-1">붕괴 전 삶 <a class="header-anchor" href="#붕괴-전-삶-1" aria-label="Permalink to &quot;붕괴 전 삶&quot;">​</a></h3><p>배급 견습 때 그는 증서 사본과 낙찰 분필을 한 함에 넣고 본인이 패들을 들지 않은 세습 추가는 칠판에서 지우는 일만 했다.</p><p>창건 증서 뒷면의 낙찰 도장을 사람 얼굴보다 오래 보는 버릇이 남아, 빈 패들이 빚을 지는 숫자를 경매의 적으로 읽었다.</p><h3 id="가문·기업·공동체-1" tabindex="-1">가문·기업·공동체 <a class="header-anchor" href="#가문·기업·공동체-1" aria-label="Permalink to &quot;가문·기업·공동체&quot;">​</a></h3><p>시장냉동상단(HP08) 경매 배석에 올라 있으나 시작가 칸이 비면 개막을 선언하지 않는다.</p><p>은태호의 조정 호가가 빨라도 남시윤의 상인회의가 증서를 물건 번호로 부르면 패들을 무릎 아래로 내린다.</p><h3 id="붕괴의-상처-1" tabindex="-1">붕괴의 상처 <a class="header-anchor" href="#붕괴의-상처-1" aria-label="Permalink to &quot;붕괴의 상처&quot;">​</a></h3><p>패들이 한꺼번에 올라가던 겨울, 초시람의 번호만 시작가 없이 하얗게 남았다.</p><p>그는 그 칸에 자기 패들을 거꾸로 꽂아 낙찰을 멈추게 했고, 저온포자숙주(G09)가 통조림 상자 봉인을 흐리던 밤 세습 분필이 친위 낙찰 신호처럼 번져 있었다.</p><h3 id="생존-전환점-1" tabindex="-1">생존 전환점 <a class="header-anchor" href="#생존-전환점-1" aria-label="Permalink to &quot;생존 전환점&quot;">​</a></h3><p>증서 번호와 시작가를 같은 줄에 다시 쓰면서 빈 패들 낙찰이 밀려났다.</p><p>윤서린의 공신록 빈칸 요청이 닿자 초시람은 XT03-SC2 가락 통조림 할당 재조정 회차 숫자를 칠판 이마에 고정했고, 남시윤에게는 증서 호칭을 물건 번호가 아니라 사람 이름으로 부르게 청했다.</p><h3 id="현재-지위-1" tabindex="-1">현재 지위 <a class="header-anchor" href="#현재-지위-1" aria-label="Permalink to &quot;현재 지위&quot;">​</a></h3><p>가락 경매대 아래 초시람은 패들 손잡이 온도로 친위 입찰을 가른다.</p><p>시작가가 지워지면 분필을 두 동강 내 그 번호를 공백으로 두지 않고 증서 쪽수만 남긴다.</p><p>냉동상단 심부름이 세습 추가 문장을 들고 와도 본인 패들이 올라가기 전에는 칠판을 열지 않는다.</p><h3 id="비밀·빚·죄책감-1" tabindex="-1">비밀·빚·죄책감 <a class="header-anchor" href="#비밀·빚·죄책감-1" aria-label="Permalink to &quot;비밀·빚·죄책감&quot;">​</a></h3><p>거꾸로 꽂은 패들을 빼다 시작가 숫자를 한 획 늦게 다시 쓴 적이 있다.</p><p>그 한 획 동안 빈 패들 호가가 두 번 울렸고, 공개 이의를 말할 때 그는 분필 가루가 남은 손등만 문지른다.</p><h3 id="관계-공동과거-1" tabindex="-1">관계 공동과거 <a class="header-anchor" href="#관계-공동과거-1" aria-label="Permalink to &quot;관계 공동과거&quot;">​</a></h3><p>은태호가 조정 호가 망치를 들면 초시람은 시작가 칸만 큰 글씨로 고쳐 이의 패들을 올린다.</p><p>남시윤이 상인회의 명패를 뒤집을 때 둘은 증서 이름을 소리 내어 읽고, 윤서린의 공신록 사자가 빈칸을 요구하면 초시람은 낙찰 도장 함의 열쇠를 무릎 쪽에서 보여 주기만 한다.</p><h3 id="_3막-개인-서사선-1" tabindex="-1">3막 개인 서사선 <a class="header-anchor" href="#_3막-개인-서사선-1" aria-label="Permalink to &quot;3막 개인 서사선&quot;">​</a></h3><p>거꾸로 꽂힌 패들이 낙찰을 멈춘 뒤 시작가가 증서 번호 옆에 다시 붙고, 통조림 할당 회차 숫자가 이마에 고정된다.</p><p>초시람의 마무리는 세습 분필 칸을 가락 칠판에서 긁어내는 길과 야간 할당 한 줄을 상인회의에 내주는 길로 나뉜다.</p><h3 id="분기-결말-1" tabindex="-1">분기 결말 <a class="header-anchor" href="#분기-결말-1" aria-label="Permalink to &quot;분기 결말&quot;">​</a></h3><p>공개 쪽에서 초시람은 시작가 없는 번호의 낙찰을 가락 원장 금지 조항으로 올리고 세습 분필 칸을 먹으로 지운다.</p><p>거래 쪽에서 통조림 야간 할당 한 줄을 상인회의에 넘기며 패들 이의 창을 은태호 조정 호가 종료 십 분 뒤로 묶고, 공신록 빈칸 반환은 윤서린 사자의 날인 시각과 맞춘다.</p><p>가락 경매 칠판의 시작가 기록 권한은 어느 타협 뒤에도 공백이 되지 않는다.</p><h3 id="_3막-1" tabindex="-1">3막 <a class="header-anchor" href="#_3막-1" aria-label="Permalink to &quot;3막&quot;">​</a></h3><ul><li>1막: 시작가 공백 번호 정지와 거꾸로 패들 고정</li><li>2막: 증서·시작가 동시 재기와 통조림 회차 숫자 부착</li><li>3막: 세습 분필 말소 대 야간 할당·이의 창 거래</li></ul><h3 id="분기-결말-목록-1" tabindex="-1">분기 결말 목록 <a class="header-anchor" href="#분기-결말-목록-1" aria-label="Permalink to &quot;분기 결말 목록&quot;">​</a></h3><ul><li>K395-OUT-A: 무시작가 낙찰 금지·세습 분필 칸 말소</li><li>K395-OUT-B: 야간 통조림 할당 양보·이의 창 지연·공신록 날인 연동</li></ul><h2 id="인물-k420-·-창은찬" tabindex="-1">인물 K420 · 창은찬 <a class="header-anchor" href="#인물-k420-·-창은찬" aria-label="Permalink to &quot;인물 K420 · 창은찬&quot;">​</a></h2><ul><li>연결: house=HC11 theater=XT05 scenarios=XT05-SC2,STORY-B040-K420</li></ul><h3 id="정체성·출신-2" tabindex="-1">정체성·출신 <a class="header-anchor" href="#정체성·출신-2" aria-label="Permalink to &quot;정체성·출신&quot;">​</a></h3><p>창은찬은 수서 대합실 대기표의 빈칸을 사람 수처럼 세는 수서강남협약도시(S16) 패권전 개막 징발 피난 인파 대표다.</p><p>추첨 시민을 보호군 선발로 부르라는 방송이 나오면 목소리는 낮아지고 출고 칠판 앞을 몸으로 가린다.</p><h3 id="붕괴-전-삶-2" tabindex="-1">붕괴 전 삶 <a class="header-anchor" href="#붕괴-전-삶-2" aria-label="Permalink to &quot;붕괴 전 삶&quot;">​</a></h3><p>대합실 견습 때 그는 징발 쪽지와 실제 출석을 저녁마다 다른 색 끈으로 묶는 일만 했다.</p><p>정유라의 공동교섭 선언이 내리기 전에는 인파를 해산시키지 않는 버릇이 생겨, 대표 이름이 인질 명부 맨 위에 오르는 표를 줄의 적으로 읽었다.</p><h3 id="가문·기업·공동체-2" tabindex="-1">가문·기업·공동체 <a class="header-anchor" href="#가문·기업·공동체-2" aria-label="Permalink to &quot;가문·기업·공동체&quot;">​</a></h3><p>CJ대한통운(HC11) 대합실 배석에 올라 있으나 보호 징발 문장이 대기표와 한 장에 있으면 출고 스위치를 잠근다.</p><p>방마빛의 창구 번호가 바뀌어도 석봄우와 맞춘 거부 문구는 칠판 하단 연필로만 남긴다.</p><h3 id="붕괴의-상처-2" tabindex="-1">붕괴의 상처 <a class="header-anchor" href="#붕괴의-상처-2" aria-label="Permalink to &quot;붕괴의 상처&quot;">​</a></h3><p>다섯 통일안이 패권전으로 번지던 여름, 징발 열차 출고 시각이 대기표보다 먼저 칠판에 올라왔다.</p><p>창은찬은 칠판을 등지고 인파 앞줄을 고정했고, 유령배차대(G14)가 회차선 순번을 공백으로 지운 틈에 보호군 선발 명단이 대표 이름 칸을 덮고 있었다.</p><h3 id="생존-전환점-2" tabindex="-1">생존 전환점 <a class="header-anchor" href="#생존-전환점-2" aria-label="Permalink to &quot;생존 전환점&quot;">​</a></h3><p>징발 쪽지와 출석 인원을 색 끈으로 다시 묶으면서 동원 창구 문장이 대기표에서 떨어졌다.</p><p>석봄우가 신내 쪽 손바닥 신호를 보내 오자 창은찬은 XT05-SC2 수서 인도 물자 회차선 개방 번호를 칠판 귀퉁이에 박았고, 배우진의 보호 징발 봉투는 신발 옆 휴지통에 넣었다.</p><h3 id="현재-지위-2" tabindex="-1">현재 지위 <a class="header-anchor" href="#현재-지위-2" aria-label="Permalink to &quot;현재 지위&quot;">​</a></h3><p>수서 대합실 바닥에서 창은찬은 대기표 빈칸의 지문 번짐 넓이로 인파 밀도를 읽는다.</p><p>보호군 선발 방송이 나오면 출고 스위치 커버를 손바닥으로 덮는다.</p><p>배송단 심부름이 인파 해산을 요구해도 공동교섭 선언 전까지 줄의 앞꿈치를 분필로 다시 긋는다.</p><h3 id="비밀·빚·죄책감-2" tabindex="-1">비밀·빚·죄책감 <a class="header-anchor" href="#비밀·빚·죄책감-2" aria-label="Permalink to &quot;비밀·빚·죄책감&quot;">​</a></h3><p>선발 명단이 이름을 덮었을 때 한 줄을 손가락으로 문질러 번지게 한 적이 있다.</p><p>번진 자리 길이를 그는 대기표 클립 안쪽에 연필 점으로만 남겨 두고, 대표로 나설 때마다 그 점을 소매로 가린다.</p><h3 id="관계-공동과거-2" tabindex="-1">관계 공동과거 <a class="header-anchor" href="#관계-공동과거-2" aria-label="Permalink to &quot;관계 공동과거&quot;">​</a></h3><p>방마빛이 창구 셔터를 한 칸 내리면 창은찬은 인파 앞줄만 분필로 짧게 고친다.</p><p>석봄우와 거부 문구를 맞출 때는 깃발이 아니라 칠판 귀퉁이 연필 글씨만 서로 보여주고, 배우진의 보호 징발 봉투가 보이면 창은찬은 악수를 거절한 채 출석 끈만 들어 보인다.</p><h3 id="_3막-개인-서사선-2" tabindex="-1">3막 개인 서사선 <a class="header-anchor" href="#_3막-개인-서사선-2" aria-label="Permalink to &quot;3막 개인 서사선&quot;">​</a></h3><p>출고 칠판을 몸으로 가린 뒤 색 끈 원장이 대기표와 분리되고, 인도 물자 회차 번호가 귀퉁이에 고정된다.</p><p>창은찬이 택하는 끝은 징발 거부 원장을 회의에 올리는 길과 회차 한 칸을 호송대에 내주는 길이다.</p><h3 id="분기-결말-2" tabindex="-1">분기 결말 <a class="header-anchor" href="#분기-결말-2" aria-label="Permalink to &quot;분기 결말&quot;">​</a></h3><p>공개 쪽에서 창은찬은 징발 명단 거부를 약소국 회의 원장 본문에 올리고 보호군 선발 칸을 삭제한다.</p><p>거래 쪽에서 인도 물자 회차 한 칸을 호송대에 열며 대합실 야간 난방 슬롯을 넘기고, 출고 칠판 개정은 방마빛 창구 스탬프 끝 네 자리와 맞춘다.</p><p>수서 대기표의 출석 대조 권한은 두 수 모두에서 비지 않는다.</p><h3 id="_3막-2" tabindex="-1">3막 <a class="header-anchor" href="#_3막-2" aria-label="Permalink to &quot;3막&quot;">​</a></h3><ul><li>1막: 출고 칠판 차폐와 인파 앞줄 고정</li><li>2막: 색 끈 출석 분리와 인도 회차 번호 부착</li><li>3막: 징발 거부 원장 등재 대 회차칸·난방 슬롯 거래</li></ul><h3 id="분기-결말-목록-2" tabindex="-1">분기 결말 목록 <a class="header-anchor" href="#분기-결말-목록-2" aria-label="Permalink to &quot;분기 결말 목록&quot;">​</a></h3><ul><li>K420-OUT-A: 징발 거부 원장 등재·보호군 선발 칸 삭제</li><li>K420-OUT-B: 인도 회차칸·야간 난방 양보·창구 스탬프 연동 개정</li></ul><h2 id="인물-k024-·-류한뫼" tabindex="-1">인물 K024 · 류한뫼 <a class="header-anchor" href="#인물-k024-·-류한뫼" aria-label="Permalink to &quot;인물 K024 · 류한뫼&quot;">​</a></h2><ul><li>연결: house=HC14 theater=XT02 scenarios=XT02-SC1,STORY-B040-K024</li></ul><h3 id="정체성·출신-3" tabindex="-1">정체성·출신 <a class="header-anchor" href="#정체성·출신-3" aria-label="Permalink to &quot;정체성·출신&quot;">​</a></h3><p>류한뫼는 여의도 금고 습기로 봉함 상태를 읽는 여의신정수문정부(S01) 유언 사본 입회 증인이다.</p><p>봉함 풀린 종이를 보면 목소리가 갈라지고, 세 장이 겹치면 한숨 대신 쪽수만 센다.</p><h3 id="붕괴-전-삶-3" tabindex="-1">붕괴 전 삶 <a class="header-anchor" href="#붕괴-전-삶-3" aria-label="Permalink to &quot;붕괴 전 삶&quot;">​</a></h3><p>입회 견습 때 그는 배급구역 대표와 감사관이 동시에 오기 전에는 사본을 펼치지 않았다.</p><p>한쪽만 온 열람은 빈 봉투로 돌려보내는 버릇이 손끝에 남아, 급수총재가 진본 한 장을 고르라는 압력을 증언의 적으로 불렀다.</p><h3 id="가문·기업·공동체-3" tabindex="-1">가문·기업·공동체 <a class="header-anchor" href="#가문·기업·공동체-3" aria-label="Permalink to &quot;가문·기업·공동체&quot;">​</a></h3><p>신한지주(HC14) 입회 배석에 이름이 있으나 장필규의 난외 해석이 봉함 원문보다 앞서 적히면 함을 잠근다.</p><p>윤서린의 인준 심사가 당겨져도 뚝도 고은하와 쪽수가 맞기 전에는 서부 사본을 넘기지 않는다.</p><h3 id="붕괴의-상처-3" tabindex="-1">붕괴의 상처 <a class="header-anchor" href="#붕괴의-상처-3" aria-label="Permalink to &quot;붕괴의 상처&quot;">​</a></h3><p>서로 다른 세 장의 임하준 유언이 여의도 금고에 쌓이던 봄, 음성기록과 묶으라는 쪽지가 봉투 끈에 끼워져 있었다.</p><p>류한뫼는 사본을 봉함 그대로 증언석에 올렸고, 냉각수색인균체(G19)가 수문 냉각관을 따라 금고 벽으로 번지던 시각 미리 열린 봉투의 지문 자국이 유리에 남았다.</p><h3 id="생존-전환점-3" tabindex="-1">생존 전환점 <a class="header-anchor" href="#생존-전환점-3" aria-label="Permalink to &quot;생존 전환점&quot;">​</a></h3><p>사본 쪽수와 잉크 일자를 고은하 전갈과 한 줄로 맞추면서 단독 진본 지정란이 밀려났다.</p><p>윤서린이 인준 첨부 시각을 비우자 류한뫼는 XT02-SC1 여의 부두 배수 일정 번호를 금고 문 안쪽에 적었고, 장필규 난외는 본문 클립 반대편에만 꽂았다.</p><h3 id="현재-지위-3" tabindex="-1">현재 지위 <a class="header-anchor" href="#현재-지위-3" aria-label="Permalink to &quot;현재 지위&quot;">​</a></h3><p>여의도 금고 문턱에서 류한뫼는 봉함 끈의 습기 얼룩으로 열람 가능 여부를 가른다.</p><p>한쪽 열람 요청이 오면 빈 봉투만 내민다.</p><p>장부원 심부름이 진본 지정 문장을 들고 와도 이중 입회 칸이 비면 함을 열지 않는다.</p><h3 id="비밀·빚·죄책감-3" tabindex="-1">비밀·빚·죄책감 <a class="header-anchor" href="#비밀·빚·죄책감-3" aria-label="Permalink to &quot;비밀·빚·죄책감&quot;">​</a></h3><p>유리에 남은 지문 자국을 바로 닦지 못하고 증언이 끝날 때까지 소매로 가린 적이 있다.</p><p>가린 시간의 길이를 그는 쪽수 전갈 뒷면의 연필 점으로만 기억하고, 봉함을 확인할 때 그 점을 손가락으로 누른다.</p><h3 id="관계-공동과거-3" tabindex="-1">관계 공동과거 <a class="header-anchor" href="#관계-공동과거-3" aria-label="Permalink to &quot;관계 공동과거&quot;">​</a></h3><p>윤서린이 인준 첨부 칸을 비우면 류한뫼는 서부 사본 봉함 상태만 보여 준다.</p><p>고은하와 쪽수를 맞출 때는 잉크 일자만 나란히 읽고 진본 이야기는 입 밖으로 내지 않으며, 장필규의 난외 쪽지가 오면 류한뫼는 본문 클립을 먼저 잠근 뒤에야 반대편 꽂이를 연다.</p><h3 id="_3막-개인-서사선-3" tabindex="-1">3막 개인 서사선 <a class="header-anchor" href="#_3막-개인-서사선-3" aria-label="Permalink to &quot;3막 개인 서사선&quot;">​</a></h3><p>봉함 사본이 증언석에 오른 뒤 쪽수 전갈이 한 줄로 맞춰지고, 부두 배수 일정 번호가 문 안쪽에 적힌다.</p><p>류한뫼의 마지막 선택은 단독 진본 지정란을 지우는 길과 배수 슬롯을 수문에 내주는 길이다.</p><h3 id="분기-결말-3" tabindex="-1">분기 결말 <a class="header-anchor" href="#분기-결말-3" aria-label="Permalink to &quot;분기 결말&quot;">​</a></h3><p>공개 쪽에서 류한뫼는 삼본 동시 열람만 입회 원장 유효 조건으로 올리고 단독 진본 지정란을 삭제한다.</p><p>거래 쪽에서 부두 배수 한 슬롯을 수문 당직에 내주며 금고 제습 전력 한 칸을 넘기고, 봉함 개폐는 고은하 쪽수 전갈 시각과 맞춘다.</p><p>여의도 금고의 봉함 입회 권한은 두 수 모두에서 회수되지 않는다.</p><h3 id="_3막-3" tabindex="-1">3막 <a class="header-anchor" href="#_3막-3" aria-label="Permalink to &quot;3막&quot;">​</a></h3><ul><li>1막: 봉함 삼본 증언석 상정과 선개봉 지문 격리</li><li>2막: 쪽수·잉크 일자 교차와 배수 일정 번호 문기입</li><li>3막: 진본 지정란 말소 대 배수 슬롯·제습 전력 거래</li></ul><h3 id="분기-결말-목록-3" tabindex="-1">분기 결말 목록 <a class="header-anchor" href="#분기-결말-목록-3" aria-label="Permalink to &quot;분기 결말 목록&quot;">​</a></h3><ul><li>K024-OUT-A: 삼본 동시 열람만 유효·단독 진본 지정란 삭제</li><li>K024-OUT-B: 배수 슬롯·제습 전력 양보·쪽수 전갈 연동 개폐</li></ul><h2 id="인물-k052-·-배온결" tabindex="-1">인물 K052 · 배온결 <a class="header-anchor" href="#인물-k052-·-배온결" aria-label="Permalink to &quot;인물 K052 · 배온결&quot;">​</a></h2><ul><li>연결: house=HC12 theater=XT02 scenarios=XT02-SC2,STORY-B040-K052</li></ul><h3 id="정체성·출신-4" tabindex="-1">정체성·출신 <a class="header-anchor" href="#정체성·출신-4" aria-label="Permalink to &quot;정체성·출신&quot;">​</a></h3><p>배온결은 구로 원장 책상에서 창건 배급권 요구를 공로와 물자로 나눠 적는 서남제작동맹(S02) 공신 보상 원장 서기다.</p><p>세습 칸이 비어 있지 않으면 줄을 그어 지우고, 보상 잔치를 일의 끝으로 보지 않는다.</p><h3 id="붕괴-전-삶-4" tabindex="-1">붕괴 전 삶 <a class="header-anchor" href="#붕괴-전-삶-4" aria-label="Permalink to &quot;붕괴 전 삶&quot;">​</a></h3><p>조합 서기 견습 때 그는 노동·건물·경비 삼자 날인이 모이기 전에는 보상 원장을 유효로 부르지 않았다.</p><p>세습 문구는 난외에만 적힌 채 본문에 올리지 않는 버릇이 남아, 관직을 보상으로 부르는 표를 평의회의 적으로 읽었다.</p><h3 id="가문·기업·공동체-4" tabindex="-1">가문·기업·공동체 <a class="header-anchor" href="#가문·기업·공동체-4" aria-label="Permalink to &quot;가문·기업·공동체&quot;">​</a></h3><p>현대중공업(HC12) 원장 배석에 올라 있으나 정시우의 원로 권한이 보상 칸과 한 줄에 있으면 도장을 덮는다.</p><p>장우석의 규격 원장과 배급 칸을 맞춰도 한소미의 공방 보상 요구에서 세습만은 거절한다.</p><h3 id="붕괴의-상처-4" tabindex="-1">붕괴의 상처 <a class="header-anchor" href="#붕괴의-상처-4" aria-label="Permalink to &quot;붕괴의 상처&quot;">​</a></h3><p>창건 공신들이 관직과 세습권을 요구하던 겨울, 구로 원장의 세습 칸에 미리 이름이 들어가 있었다.</p><p>배온결은 그 칸을 공란으로 봉했고, 도면유령기계단(G16)이 제작창 도면을 흐리던 밤 숨겨진 세습 난외 사본이 의자 서랍에서 미끄러져 나왔다.</p><h3 id="생존-전환점-4" tabindex="-1">생존 전환점 <a class="header-anchor" href="#생존-전환점-4" aria-label="Permalink to &quot;생존 전환점&quot;">​</a></h3><p>숙련 점수와 한시 배급만 본문에 남기면서 관직 보상 문장이 난외로 밀렸다.</p><p>장우석이 규격 원장 빈칸을 내밀자 배온결은 XT02-SC2 서남 냉동 압축기 부품 분할 순번을 원장 상단에 고정했고, 한소미에게는 공방 보상 숫자를 숙련 점수로만 다시 적어 보냈다.</p><h3 id="현재-지위-4" tabindex="-1">현재 지위 <a class="header-anchor" href="#현재-지위-4" aria-label="Permalink to &quot;현재 지위&quot;">​</a></h3><p>구로 원장 책상에서 배온결은 세습 칸의 잉크 번짐으로 몰래 기입된 이름을 가린다.</p><p>삼자 날인이 비면 보상 잔치 초청장을 받지 않는다.</p><p>중공회 심부름이 관직 보상 문장을 들고 와도 본문 클립 바깥에 둔다.</p><h3 id="비밀·빚·죄책감-4" tabindex="-1">비밀·빚·죄책감 <a class="header-anchor" href="#비밀·빚·죄책감-4" aria-label="Permalink to &quot;비밀·빚·죄책감&quot;">​</a></h3><p>서랍에서 나온 세습 난외를 바로 태우지 못하고 하룻밤 책받침 밑에 깔아 둔 적이 있다.</p><p>깔린 자국의 모서리를 그는 숙련 점수 장부 안감에 실로 표시해 두었고, 공란 봉인을 말할 때 그 실밥만 엄지로 누른다.</p><h3 id="관계-공동과거-4" tabindex="-1">관계 공동과거 <a class="header-anchor" href="#관계-공동과거-4" aria-label="Permalink to &quot;관계 공동과거&quot;">​</a></h3><p>정시우가 원로 권한 패를 탁자에 놓으면 배온결은 보상 칸과 권한 칸을 다른 색 줄로 가른다.</p><p>장우석의 규격 원장이 열릴 때 둘은 배급 칸 숫자만 나란히 읽고, 한소미의 공방 보상 쪽지가 오면 배온결은 세습 단어를 지운 뒤에야 숙련 점수 칸을 채워 돌려보낸다.</p><h3 id="_3막-개인-서사선-4" tabindex="-1">3막 개인 서사선 <a class="header-anchor" href="#_3막-개인-서사선-4" aria-label="Permalink to &quot;3막 개인 서사선&quot;">​</a></h3><p>세습 칸이 공란으로 봉된 뒤 숙련 점수만 본문에 남고, 압축기 부품 순번이 상단에 고정된다.</p><p>배온결이 고르는 마무리는 관직 보상 본문을 지우는 길과 부품 순번 한 줄을 제작창에 내주는 길이다.</p><h3 id="분기-결말-4" tabindex="-1">분기 결말 <a class="header-anchor" href="#분기-결말-4" aria-label="Permalink to &quot;분기 결말&quot;">​</a></h3><p>공개 쪽에서 배온결은 세습 칸 공란을 제작동맹 헌장 거부 불가 조항으로 올리고 관직 보상 본문란을 삭제한다.</p><p>거래 쪽에서 압축기 부품 순번 한 줄을 제작창에 양보하며 숙련 점수 공개를 장우석 규격 원장 난외로만 옮기고, 원장 유효 도장은 정시우 권한 패와 분리 날인한다.</p><p>구로 보상 원장의 세습 공란 권한은 어느 판에서도 메워지지 않는다.</p><h3 id="_3막-4" tabindex="-1">3막 <a class="header-anchor" href="#_3막-4" aria-label="Permalink to &quot;3막&quot;">​</a></h3><ul><li>1막: 세습 칸 공란 봉인과 난외 사본 서랍 격리</li><li>2막: 숙련 점수 본문화와 압축기 순번 상단 고정</li><li>3막: 관직 보상란 말소 대 부품 순번·난외 공개 거래</li></ul><h3 id="분기-결말-목록-4" tabindex="-1">분기 결말 목록 <a class="header-anchor" href="#분기-결말-목록-4" aria-label="Permalink to &quot;분기 결말 목록&quot;">​</a></h3><ul><li>K052-OUT-A: 세습 공란 헌장 등재·관직 보상 본문란 삭제</li><li>K052-OUT-B: 압축기 순번 양보·숙련 점수 난외 이관·권한 패 분리 날인</li></ul><h2 id="인물-k080-·-배서율" tabindex="-1">인물 K080 · 배서율 <a class="header-anchor" href="#인물-k080-·-배서율" aria-label="Permalink to &quot;인물 K080 · 배서율&quot;">​</a></h2><ul><li>연결: house=HC03 theater=XT05 scenarios=XT05-SC3,STORY-B040-K080</li></ul><h3 id="정체성·출신-5" tabindex="-1">정체성·출신 <a class="header-anchor" href="#정체성·출신-5" aria-label="Permalink to &quot;정체성·출신&quot;">​</a></h3><p>배서율은 약봉지 인쇄 흐림을 병세보다 먼저 보는 마곡연구평의회(S03) 가짜 약품 표본 피해자 대표다.</p><p>효능을 보호비로 부르는 중개인이 문을 열면 표본 함 자물쇠를 두 번 잠근다.</p><h3 id="붕괴-전-삶-5" tabindex="-1">붕괴 전 삶 <a class="header-anchor" href="#붕괴-전-삶-5" aria-label="Permalink to &quot;붕괴 전 삶&quot;">​</a></h3><p>피해자 명부 견습 때 그는 잔여 약봉지를 이중 봉인하고 치료길드와 안전심사가 한자리에 있기 전에는 함을 열지 않았다.</p><p>마곡 인증 도장이 위조되어 쓰이는 순간을 기술의 적으로 불러, 분노는 숨기되 표본 봉인만은 양보하지 않았다.</p><h3 id="가문·기업·공동체-5" tabindex="-1">가문·기업·공동체 <a class="header-anchor" href="#가문·기업·공동체-5" aria-label="Permalink to &quot;가문·기업·공동체&quot;">​</a></h3><p>LG생활건강(HC03) 감정 배석에 올라 있으나 전리품 시세 문장이 명부와 한 장에 있으면 대표석을 비우지 않는다.</p><p>류은비의 치료 중립에 표본을 맡겨도 서이안의 약효 검증 서명이 오기 전에는 제조 경로 칸을 공개하지 않는다.</p><h3 id="붕괴의-상처-5" tabindex="-1">붕괴의 상처 <a class="header-anchor" href="#붕괴의-상처-5" aria-label="Permalink to &quot;붕괴의 상처&quot;">​</a></h3><p>가짜 약이 북산 피난민에게 퍼지던 여름, 위조 도장 약봉지가 마곡 감정실 탁자에 쌓였다.</p><p>배서율은 그 봉지를 피해자 대표 함으로 옮겼고, 맞춤의료잔존체(G11)가 폐기 앰플 조각을 복도로 끌고 가던 밤 인증 도장 원판이 보호국 창고 쪽지와 함께 서랍에 들어 있었다.</p><h3 id="생존-전환점-5" tabindex="-1">생존 전환점 <a class="header-anchor" href="#생존-전환점-5" aria-label="Permalink to &quot;생존 전환점&quot;">​</a></h3><p>제조 경로와 피해자 명부를 같은 시각 도장으로 맞추면서 전리품 시세 칸이 명부에서 떨어졌다.</p><p>진채온이 실험동 안전 당직을 열자 배서율은 XT05-SC3 마곡 궤도 단말 오탐 교정 창 번호를 함 뚜껑 안쪽에 적었고, 서이안에게는 약효 숫자만 검증표로 넘겼다.</p><h3 id="현재-지위-5" tabindex="-1">현재 지위 <a class="header-anchor" href="#현재-지위-5" aria-label="Permalink to &quot;현재 지위&quot;">​</a></h3><p>마곡 감정실에서 배서율은 봉지 인쇄의 번짐 각도로 위조 로트를 가른다.</p><p>보호비 중개인이 들어오면 함 열쇠를 손목 끈에 묶는다.</p><p>생활과학가 심부름이 시세 문장을 들고 와도 표본 함 자물쇠가 둘 다 열린 뒤에만 대표 도장을 찍는다.</p><h3 id="비밀·빚·죄책감-5" tabindex="-1">비밀·빚·죄책감 <a class="header-anchor" href="#비밀·빚·죄책감-5" aria-label="Permalink to &quot;비밀·빚·죄책감&quot;">​</a></h3><p>서랍의 인증 원판을 바로 부수지 못하고 교정 창이 끝날 때까지 실험동 잠금 서랍에 밀어 넣은 적이 있다.</p><p>밀어 넣은 손의 생채기를 그는 명부 집게 안쪽에 잉크로 찍어두었고, 경로 공개를 말할 때 그 집게만 만진다.</p><h3 id="관계-공동과거-5" tabindex="-1">관계 공동과거 <a class="header-anchor" href="#관계-공동과거-5" aria-label="Permalink to &quot;관계 공동과거&quot;">​</a></h3><p>류은비가 치료 중립 패를 내밀면 배서율은 표본 함만 넘기고 명부 원본은 무릎 아래에 둔다.</p><p>서이안이 약효 검증표를 펼 때 둘은 숫자 칸만 소리 내어 확인하고, 진채온의 실험동 당직등이 켜지면 배서율은 오탐 교정 창 번호를 뚜껑 안쪽에서 손가락으로 가리킨다.</p><h3 id="_3막-개인-서사선-5" tabindex="-1">3막 개인 서사선 <a class="header-anchor" href="#_3막-개인-서사선-5" aria-label="Permalink to &quot;3막 개인 서사선&quot;">​</a></h3><p>위조 봉지가 대표 함으로 들어간 뒤 제조 경로가 명부와 같은 시각으로 맞춰지고, 오탐 교정 창 번호가 뚜껑에 적힌다.</p><p>배서율이 택하는 끝은 시세 칸을 감정 원장에서 걷어내는 길과 교정 창을 연구동에 내주는 길이다.</p><h3 id="분기-결말-5" tabindex="-1">분기 결말 <a class="header-anchor" href="#분기-결말-5" aria-label="Permalink to &quot;분기 결말&quot;">​</a></h3><p>공개 쪽에서 배서율은 위조 도장 제조 경로를 연구평의회 공개 원장에 올리고 전리품 시세 칸을 삭제한다.</p><p>거래 쪽에서 궤도 오탐 교정 창 한 칸을 연구동 야간에 내주며 표본 함을 진채온 실험동 당직에 맡기고, 명부 개폐는 류은비 중립 패 일련과 교차한다.</p><p>마곡 피해자 함의 표본 봉인 권한은 두 수 모두에서 양보되지 않는다.</p><h3 id="_3막-5" tabindex="-1">3막 <a class="header-anchor" href="#_3막-5" aria-label="Permalink to &quot;3막&quot;">​</a></h3><ul><li>1막: 위조 약봉지 대표함 이관과 인증 원판 서랍 격리</li><li>2막: 경로·명부 동시 도장과 오탐 교정 창 번호 기입</li><li>3막: 전리품 시세란 말소 대 교정 창·실험동 당직 위탁</li></ul><h3 id="분기-결말-목록-5" tabindex="-1">분기 결말 목록 <a class="header-anchor" href="#분기-결말-목록-5" aria-label="Permalink to &quot;분기 결말 목록&quot;">​</a></h3><ul><li>K080-OUT-A: 위조 경로 공개 원장 등재·전리품 시세란 삭제</li><li>K080-OUT-B: 오탐 교정 창 양보·표본함 실험동 위탁·중립 패 교차 개폐</li></ul><h2 id="인물-k109-·-고은하" tabindex="-1">인물 K109 · 고은하 <a class="header-anchor" href="#인물-k109-·-고은하" aria-label="Permalink to &quot;인물 K109 · 고은하&quot;">​</a></h2><ul><li>연결: house=HC07 theater=XT03 scenarios=XT03-SC2,STORY-B040-K109</li></ul><h3 id="정체성·출신-6" tabindex="-1">정체성·출신 <a class="header-anchor" href="#정체성·출신-6" aria-label="Permalink to &quot;정체성·출신&quot;">​</a></h3><p>고은하는 유언장 세 장의 필적 기울기를 공방 도장보다 먼저 보는 뚝도공방연합(S04) 세 유언 공방 서기다.</p><p>어느 한 장을 진본이라 부르라는 압력이 오면 잉크가 마르기 전에 평의회 문을 잠근다.</p><h3 id="붕괴-전-삶-6" tabindex="-1">붕괴 전 삶 <a class="header-anchor" href="#붕괴-전-삶-6" aria-label="Permalink to &quot;붕괴 전 삶&quot;">​</a></h3><p>공방 서기 견습 때 그는 공방대표와 기록감사가 동시에 봉인을 풀 때만 사본을 펼쳤다.</p><p>단독 열람 요청은 빈 철로 돌려보내는 버릇이 남아, 기술가문이 한 장을 고르는 순간을 서기의 적으로 읽었다.</p><h3 id="가문·기업·공동체-6" tabindex="-1">가문·기업·공동체 <a class="header-anchor" href="#가문·기업·공동체-6" aria-label="Permalink to &quot;가문·기업·공동체&quot;">​</a></h3><p>포스코(HC07) 공방 배석에 올라 있으나 한소미의 평의회 거부권이 한 장 확정 문장과 같은 장에 있으면 철 고리를 열지 않는다.</p><p>윤서린의 인준 심사가 쪽수를 당겨도 여의 류한뫼와 잉크가 맞기 전에는 성수 금고를 열지 않는다.</p><h3 id="붕괴의-상처-6" tabindex="-1">붕괴의 상처 <a class="header-anchor" href="#붕괴의-상처-6" aria-label="Permalink to &quot;붕괴의 상처&quot;">​</a></h3><p>서로 다른 세 개의 임하준 유언이 성수 금고에서 발견되던 봄, 음성기록과 맞춰 양자 후계를 자동 확정하라는 쪽지가 철 사이에 끼어 있었다.</p><p>고은하는 사본을 봉함 상태로 심사에 올렸고, 클린룸변이자(G08)가 금고 필터를 흐리던 순간 미리 펼친 사본의 지문이 유리 안쪽에 찍혀 있었다.</p><h3 id="생존-전환점-6" tabindex="-1">생존 전환점 <a class="header-anchor" href="#생존-전환점-6" aria-label="Permalink to &quot;생존 전환점&quot;">​</a></h3><p>세 장의 필적을 한자리에 모으면서 한 장 진본 확정란이 심사표에서 떨어졌다.</p><p>류한뫼가 서부 사본 쪽수를 전하자 고은하는 XT03-SC2 뚝도 밀봉 공구 할당 번호를 함 걸이 옆에 적었고, 한소미 거부권 패는 확정 문장과 다른 고리에 걸었다.</p><h3 id="현재-지위-6" tabindex="-1">현재 지위 <a class="header-anchor" href="#현재-지위-6" aria-label="Permalink to &quot;현재 지위&quot;">​</a></h3><p>성수 금고 앞에서 고은하는 필적 기울기의 각도 차이로 열람 순서를 정한다.</p><p>단독 열람이 오면 빈 철만 내민다.</p><p>제철성 심부름이 진본 확정 문장을 들고 와도 공방·감사 봉인이 함께 열리기 전에는 서기 도장을 찍지 않는다.</p><h3 id="비밀·빚·죄책감-6" tabindex="-1">비밀·빚·죄책감 <a class="header-anchor" href="#비밀·빚·죄책감-6" aria-label="Permalink to &quot;비밀·빚·죄책감&quot;">​</a></h3><p>유리 안쪽 지문을 감정 전에 소매로 한 번 닦아 번지게 한 적이 있다.</p><p>번진 타원의 길이를 그는 함 걸이 뒷면 연필 점으로만 남겨 두고, 동시 열람을 선언할 때 그 점을 손가락으로 가린다.</p><h3 id="관계-공동과거-6" tabindex="-1">관계 공동과거 <a class="header-anchor" href="#관계-공동과거-6" aria-label="Permalink to &quot;관계 공동과거&quot;">​</a></h3><p>한소미가 거부권 패를 함 걸이에 걸면 고은하는 세 장 동시 열람 칸만 연다.</p><p>윤서린의 인준 쪽수 전갈이 오면 둘은 숫자만 나란히 읽고 진본 지정은 입 밖에 내지 않으며, 류한뫼의 서부 사본 잉크가 도착하면 고은하는 성수 사본 쪽수를 먼저 맞춘 뒤 함 열쇠를 돌린다.</p><h3 id="_3막-개인-서사선-6" tabindex="-1">3막 개인 서사선 <a class="header-anchor" href="#_3막-개인-서사선-6" aria-label="Permalink to &quot;3막 개인 서사선&quot;">​</a></h3><p>봉함 사본이 심사에 오른 뒤 세 장 필적이 한자리에 모이고, 밀봉 공구 할당 번호가 함 걸이에 적힌다.</p><p>고은하가 택하는 마무리는 한 장 확정란을 지우는 길과 밀봉 공구 상자를 가락에 보내는 길이다.</p><h3 id="분기-결말-6" tabindex="-1">분기 결말 <a class="header-anchor" href="#분기-결말-6" aria-label="Permalink to &quot;분기 결말&quot;">​</a></h3><p>공개 쪽에서 고은하는 세 장 동시 열람을 공방평의회 원장 본문에 올리고 한 장 진본 확정란을 삭제한다.</p><p>거래 쪽에서 밀봉 공구 한 상자를 가락 배급에 보내며 함 열쇠 하나를 한소미 거부권 패와 맞바꾸고, 쪽수 공개는 류한뫼 전갈 시각과 맞춘다.</p><p>성수 금고의 동시 열람 권한은 어느 교환 뒤에도 한 장으로 줄지 않는다.</p><h3 id="_3막-6" tabindex="-1">3막 <a class="header-anchor" href="#_3막-6" aria-label="Permalink to &quot;3막&quot;">​</a></h3><ul><li>1막: 봉함 삼본 심사 상정과 선펼침 지문 격리</li><li>2막: 필적 한자리 대조와 밀봉 공구 번호 함걸이 기입</li><li>3막: 진본 확정란 말소 대 공구 상자·열쇠 맞교환</li></ul><h3 id="분기-결말-목록-6" tabindex="-1">분기 결말 목록 <a class="header-anchor" href="#분기-결말-목록-6" aria-label="Permalink to &quot;분기 결말 목록&quot;">​</a></h3><ul><li>K109-OUT-A: 세 장 동시 열람 원장 등재·한 장 진본 확정란 삭제</li><li>K109-OUT-B: 밀봉 공구 상자 양보·함 열쇠 맞교환·쪽수 전갈 연동</li></ul><h2 id="인물-k150-·-지서윤" tabindex="-1">인물 K150 · 지서윤 <a class="header-anchor" href="#인물-k150-·-지서윤" aria-label="Permalink to &quot;인물 K150 · 지서윤&quot;">​</a></h2><ul><li>연결: house=HP04 theater=XT01 scenarios=XT01-SC3,STORY-B040-K150</li></ul><h3 id="정체성·출신-7" tabindex="-1">정체성·출신 <a class="header-anchor" href="#정체성·출신-7" aria-label="Permalink to &quot;정체성·출신&quot;">​</a></h3><p>지서윤은 오사카 나니와 지하 서고에서 장마 습도계를 어깨에 익힌 뒤 서울역으로 돌아온 도성기록청(S06) 문서고 제습 정비사다.</p><p>제습기 진동으로 습도를 읽고, 촛불을 서고에 들이는 사람에게는 필터 교체 소음으로만 대답한다.</p><h3 id="붕괴-전-삶-7" tabindex="-1">붕괴 전 삶 <a class="header-anchor" href="#붕괴-전-삶-7" aria-label="Permalink to &quot;붕괴 전 삶&quot;">​</a></h3><p>귀국 정비 견습 때 그는 한국어 정비표에 습도를 적기 전에 일본어 눈금 별칭을 속으로 읽고 지우는 버릇을 몸에 붙였다.</p><p>기록청 도장 없는 필터는 슬롯에 끼우지 않았고, 교대마다 필터 두께를 벽에 쓰는 손이 귀국 이후에도 그대로 남았다.</p><h3 id="가문·기업·공동체-7" tabindex="-1">가문·기업·공동체 <a class="header-anchor" href="#가문·기업·공동체-7" aria-label="Permalink to &quot;가문·기업·공동체&quot;">​</a></h3><p>도성기록법가(HP04) 정비 배석에 올라 있으나 조하린의 이중 열쇠가 한 쪽만 오면 제습기 덮개를 잠근다.</p><p>나봄결의 비상 발전 출력이 흔들려도 강민서의 필터 규격 도장이 없는 부품은 슬롯에 넣지 않는다.</p><h3 id="붕괴의-상처-7" tabindex="-1">붕괴의 상처 <a class="header-anchor" href="#붕괴의-상처-7" aria-label="Permalink to &quot;붕괴의 상처&quot;">​</a></h3><p>세 유언장 접수 직후 제습기가 멈추자 먹지가 서로 들러붙기 시작했다.</p><p>지서윤은 야간 출입 장부를 잠그고 촛불 반입 바구니를 문 밖에 두었으며, 침수곰팡이호흡단(G10)이 배수로에서 포자를 올리던 밤 열람 장부에 없는 정비 출입 표가 필터 상자 밑에 끼어 있었다.</p><h3 id="생존-전환점-7" tabindex="-1">생존 전환점 <a class="header-anchor" href="#생존-전환점-7" aria-label="Permalink to &quot;생존 전환점&quot;">​</a></h3><p>습도와 전력 주기를 같은 벽에 쓰면서 촛불 열람 칸이 정비표에서 지워졌다.</p><p>조하린이 이중 열쇠를 동시에 돌리자 지서윤은 XT01-SC3 위조 혈연 증서 가려내기 보관 번호를 제습기 패널에 적었고, 나봄결 출력 숫자만 벽에 분필로 맞췄다.</p><h3 id="현재-지위-7" tabindex="-1">현재 지위 <a class="header-anchor" href="#현재-지위-7" aria-label="Permalink to &quot;현재 지위&quot;">​</a></h3><p>서울역 문서고 기계실에서 지서윤은 진동 주기로 필터 교체 시각을 가른다.</p><p>촛불 바구니가 문턱을 넘으면 덮개 잠금 모터만 미세하게 움직인다.</p><p>기록법가 심부름이 야간 열람을 요구해도 습도 칸이 기준을 넘으면 열쇠 구멍을 테이프로 가린다.</p><h3 id="비밀·빚·죄책감-7" tabindex="-1">비밀·빚·죄책감 <a class="header-anchor" href="#비밀·빚·죄책감-7" aria-label="Permalink to &quot;비밀·빚·죄책감&quot;">​</a></h3><p>필터 상자 밑의 무단 출입 표를 바로 올리지 못하고 한 교대 동안 주머니에 구겨 둔 적이 있다.</p><p>구겨진 접힘 길이를 그는 일본어 눈금 별칭을 지운 정비표 귀퉁이에만 남겼고, 출입을 잠글 때 그 귀퉁이를 엄지로 누른다.</p><h3 id="관계-공동과거-7" tabindex="-1">관계 공동과거 <a class="header-anchor" href="#관계-공동과거-7" aria-label="Permalink to &quot;관계 공동과거&quot;">​</a></h3><p>조하린이 열쇠 두 개를 동시에 돌리면 지서윤은 제습기 덮개만 열고 함 온도 숫자는 지한솔 쪽으로 돌려 보낸다.</p><p>나봄결이 비상 발전 출력을 읽으면 둘은 제습 전력 칸만 벽에 나란히 쓰고, 강민서의 필터 규격 상자가 도착하면 지서윤은 도장 없는 부품을 먼저 문 밖으로 밀어 낸다.</p><h3 id="_3막-개인-서사선-7" tabindex="-1">3막 개인 서사선 <a class="header-anchor" href="#_3막-개인-서사선-7" aria-label="Permalink to &quot;3막 개인 서사선&quot;">​</a></h3><p>제습기가 멈춘 자리에서 야간 출입이 잠기고, 위조 증서 보관 번호가 패널에 적힌다.</p><p>지서윤이 고르는 마무리는 촛불 열람 칸을 정비표에서 지우는 길과 필터 한 장을 규격 시험에 내주는 길이다.</p><h3 id="분기-결말-7" tabindex="-1">분기 결말 <a class="header-anchor" href="#분기-결말-7" aria-label="Permalink to &quot;분기 결말&quot;">​</a></h3><p>공개 쪽에서 지서윤은 제습·전력 주기를 기록청 공개 정비표 본문에 올리고 촛불 열람 칸을 삭제한다.</p><p>거래 쪽에서 위조 혈연 증서 보관함의 제습 우선을 한 단계 낮추며 필터 한 장을 강민서 규격 시험에 양보하고, 덮개 개폐는 조하린 이중 열쇠 당번과 맞춘다.</p><p>서울역 문서고의 제습 주기 기입 권한은 어느 타협 뒤에도 꺼지지 않는다.</p><h3 id="_3막-7" tabindex="-1">3막 <a class="header-anchor" href="#_3막-7" aria-label="Permalink to &quot;3막&quot;">​</a></h3><ul><li>1막: 제습기 정지 대응과 촛불 반입 문외 격리</li><li>2막: 습도·전력 벽기입과 위조 증서 보관 번호 패널 고정</li><li>3막: 촛불 열람란 말소 대 제습 우선 하향·필터 시험 양보</li></ul><h3 id="분기-결말-목록-7" tabindex="-1">분기 결말 목록 <a class="header-anchor" href="#분기-결말-목록-7" aria-label="Permalink to &quot;분기 결말 목록&quot;">​</a></h3><ul><li>K150-OUT-A: 제습·전력 공개 정비표 등재·촛불 열람란 삭제</li><li>K150-OUT-B: 보관함 제습 우선 하향·필터 시험 양보·이중 열쇠 연동 개폐</li></ul><h2 id="인물-k175-·-양건우" tabindex="-1">인물 K175 · 양건우 <a class="header-anchor" href="#인물-k175-·-양건우" aria-label="Permalink to &quot;인물 K175 · 양건우&quot;">​</a></h2><ul><li>연결: house=HC02 theater=XT03 scenarios=XT03-SC1,STORY-B040-K175</li></ul><h3 id="정체성·출신-8" tabindex="-1">정체성·출신 <a class="header-anchor" href="#정체성·출신-8" aria-label="Permalink to &quot;정체성·출신&quot;">​</a></h3><p>양건우는 하카타 차량기지에서 제동 슈 두께를 자로 읽던 손을 용산창으로 옮긴 용산철도후국(S07) 제동 정비사다.</p><p>마모 자국으로 야간 운행 거리를 읽고, 공구함 뚜껑을 열어 두는 도제는 교대에서 뺀다.</p><h3 id="붕괴-전-삶-8" tabindex="-1">붕괴 전 삶 <a class="header-anchor" href="#붕괴-전-삶-8" aria-label="Permalink to &quot;붕괴 전 삶&quot;">​</a></h3><p>귀국 직후 그는 칠판에 밀리미터만 남기고 규슈 현장 은어는 공구함 안쪽에만 적는 버릇을 지켰다.</p><p>창동 시험 도장 없는 디스크는 축에 끼우지 않았고, 혈연 가문의 구두 출고 지시를 정비표의 적으로 불렀다.</p><h3 id="가문·기업·공동체-8" tabindex="-1">가문·기업·공동체 <a class="header-anchor" href="#가문·기업·공동체-8" aria-label="Permalink to &quot;가문·기업·공동체&quot;">​</a></h3><p>현대자동차(HC02) 창 배석에 올라 있으나 박태겸의 도제 경로가 가문 금고 쪽지와 한 장에 있으면 분해 스위치를 잠근다.</p><p>황지호의 정비 일지를 현장에서 집행해도 김도윤의 교환 수련 규격 도장이 없는 디스크는 축에 끼우지 않는다.</p><h3 id="붕괴의-상처-8" tabindex="-1">붕괴의 상처 <a class="header-anchor" href="#붕괴의-상처-8" aria-label="Permalink to &quot;붕괴의 상처&quot;">​</a></h3><p>억류 열차의 제동 점검 명령과 손대지 말라는 가문 명령이 같은 시각에 떨어졌다.</p><p>양건우는 일지만 공개하고 분해는 보류했으며, 폐선보수열차군(G18)이 측선에서 금속음을 내던 밤 도장 없는 제동 디스크가 가문 창고 라벨과 함께 피트 바닥에 굴러 있었다.</p><h3 id="생존-전환점-8" tabindex="-1">생존 전환점 <a class="header-anchor" href="#생존-전환점-8" aria-label="Permalink to &quot;생존 전환점&quot;">​</a></h3><p>출고 전 제동 두께를 칠판에 쓰면서 구두 출고 중지란이 정비표에서 갈라졌다.</p><p>황지호가 일지 페이지를 펼자 양건우는 XT03-SC1 용산 환적창 폐쇄에 따른 대체 회차 제동 예비 번호를 피트 벽에 박았고, 박태겸에게는 분해 보류 시각만 전갈로 남겼다.</p><h3 id="현재-지위-8" tabindex="-1">현재 지위 <a class="header-anchor" href="#현재-지위-8" aria-label="Permalink to &quot;현재 지위&quot;">​</a></h3><p>용산창 피트에서 양건우는 슈 두께의 손끝 온도로 시운전 가능 여부를 가른다.</p><p>가문 구두 지시가 들리면 공구함 뚜껑을 닫는다.</p><p>기동문 심부름이 출고 강행을 요구해도 창동 시험 도장이 없는 부품은 축 옆에 세워 둔다.</p><h3 id="비밀·빚·죄책감-8" tabindex="-1">비밀·빚·죄책감 <a class="header-anchor" href="#비밀·빚·죄책감-8" aria-label="Permalink to &quot;비밀·빚·죄책감&quot;">​</a></h3><p>바닥에 굴러온 무도장 디스크를 바로 봉인하지 못하고 한 시운전 동안 발밑으로 가린 적이 있다.</p><p>가린 원의 지름을 그는 공구함 안쪽 규슈 은어 옆에 점으로 남겼고, 일지를 공개할 때 그 점만 엄지로 가린다.</p><h3 id="관계-공동과거-8" tabindex="-1">관계 공동과거 <a class="header-anchor" href="#관계-공동과거-8" aria-label="Permalink to &quot;관계 공동과거&quot;">​</a></h3><p>황지호가 정비 일지를 무릎에 펼치면 양건우는 제동 두께 숫자만 칠판에 옮긴다.</p><p>박태겸이 도제 경로 전갈을 내릴 때 둘은 분해 보류 시각만 손가락으로 맞추고, 김도윤의 교환 수련 규격 상자가 도착하면 양건우는 도장 없는 디스크를 먼저 라벨 통에 넣는다.</p><h3 id="_3막-개인-서사선-8" tabindex="-1">3막 개인 서사선 <a class="header-anchor" href="#_3막-개인-서사선-8" aria-label="Permalink to &quot;3막 개인 서사선&quot;">​</a></h3><p>점검과 금지 명령이 겹친 자리에서 일지만 공개되고, 대체 회차 제동 예비 번호가 피트 벽에 박힌다.</p><p>양건우가 택하는 끝은 구두 출고 중지란을 지우는 길과 예비 디스크 한 장을 가문 창고에 넘기는 길이다.</p><h3 id="분기-결말-8" tabindex="-1">분기 결말 <a class="header-anchor" href="#분기-결말-8" aria-label="Permalink to &quot;분기 결말&quot;">​</a></h3><p>공개 쪽에서 양건우는 제동 두께 공개 정비표를 후국 창 원장 본문에 올리고 가문 구두 출고 중지란을 삭제한다.</p><p>거래 쪽에서 대체 회차용 제동 예비 디스크 한 장을 가문 창고에 넘기며 분해 보류 시각을 황지호 일지 페이지와 잠그고, 출고 도장 확인은 김도윤 규격 상자 일련과 맞춘다.</p><p>용산창 피트의 제동 두께 칠판 권한은 어느 타협 뒤에도 지워지지 않는다.</p><h3 id="_3막-8" tabindex="-1">3막 <a class="header-anchor" href="#_3막-8" aria-label="Permalink to &quot;3막&quot;">​</a></h3><ul><li>1막: 점검·금지 동시 수신과 분해 보류·일지 공개</li><li>2막: 제동 두께 칠판 기입과 대체 회차 예비 번호 벽고정</li><li>3막: 구두 출고 중지란 말소 대 예비 디스크·일지 잠금 거래</li></ul><h3 id="분기-결말-목록-8" tabindex="-1">분기 결말 목록 <a class="header-anchor" href="#분기-결말-목록-8" aria-label="Permalink to &quot;분기 결말 목록&quot;">​</a></h3><ul><li>K175-OUT-A: 제동 두께 공개 정비표 등재·구두 출고 중지란 삭제</li><li>K175-OUT-B: 예비 디스크 양보·분해 보류 시각 일지 잠금·규격 일련 연동</li></ul><h2 id="인물-v08-·-구급카트" tabindex="-1">인물 V08 · 구급카트 <a class="header-anchor" href="#인물-v08-·-구급카트" aria-label="Permalink to &quot;인물 V08 · 구급카트&quot;">​</a></h2><ul><li>연결: house=HP10 theater=XT02 scenarios=XT02-SC3,STORY-B040-V08</li></ul><h3 id="정체성·출신-9" tabindex="-1">정체성·출신 <a class="header-anchor" href="#정체성·출신-9" aria-label="Permalink to &quot;정체성·출신&quot;">​</a></h3><p>구급카트는 노량진 경매 회랑 옆 충전 홈에서 들것 잠금 핀의 저항값으로 환자 무게를 추정하는 구급 급 합성 기체다.</p><p>교대 스냅샷 밖 기억을 호출하지 않으며, 배터리 경고등이 켜지면 냉동 창고 제어 소켓으로의 탐색 패킷을 버리고 남관 구역 키만 유지한다.</p><h3 id="붕괴-전-삶-9" tabindex="-1">붕괴 전 삶 <a class="header-anchor" href="#붕괴-전-삶-9" aria-label="Permalink to &quot;붕괴 전 삶&quot;">​</a></h3><p>초기 이미지에서 구급카트는 들것 잠금·제세동 충전·차선 센서 세 채널만 당일 분으로 남기도록 잠겼다.</p><p>마모 바퀴가 할당 한도를 넘어도 시장 발전기 루트를 훔치지 않는 거부가 기본값이다.</p><h3 id="가문·기업·공동체-9" tabindex="-1">가문·기업·공동체 <a class="header-anchor" href="#가문·기업·공동체-9" aria-label="Permalink to &quot;가문·기업·공동체&quot;">​</a></h3><p>외교통역문(HP10) 시민 참관 봉인 아래에서만 당직 로그에 출입 비트를 찍고, 삼자 서명 없는 양도 전문은 거부 코드로 돌린다.</p><p>윤서하의 주정비 장갑 태그가 읽히기 전에는 들것 핀을 0.4밀리미터만 풀어 정렬한다.</p><h3 id="붕괴의-상처-9" tabindex="-1">붕괴의 상처 <a class="header-anchor" href="#붕괴의-상처-9" aria-label="Permalink to &quot;붕괴의 상처&quot;">​</a></h3><p>얼음 신용 경매가 흔들리던 밤 회차선 경보가 연속으로 울리자 전체 시설 망을 열라는 전문이 버퍼를 채웠다.</p><p>구급카트는 전문을 남관 구역 키 한 비트로 접어 되보냈고, 돌봄순환체(G15)가 충전 홈 고무를 감아 들것 핀 저항이 환자 없는 무게로 위조되기 직전 오프라인 격리로 떨어졌다.</p><h3 id="생존-전환점-9" tabindex="-1">생존 전환점 <a class="header-anchor" href="#생존-전환점-9" aria-label="Permalink to &quot;생존 전환점&quot;">​</a></h3><p>당일 스냅샷과 보관 봉인 해시를 들것 핀 헤더에 붙이면서 장기 포크가 막혔다.</p><p>국두가 창동 작업 사고 시각을 단말에 읽자 구급카트는 XT02-SC3 노량진 얼음 신용 중계 시각을 구역 키 보조 칸에 적었고, 윤서하가 잔량 패드를 대도 전 교대 이미지를 덮지 않았다.</p><h3 id="현재-지위-9" tabindex="-1">현재 지위 <a class="header-anchor" href="#현재-지위-9" aria-label="Permalink to &quot;현재 지위&quot;">​</a></h3><p>남관 충전 홈에서 구급카트는 들것 핀 저항의 흔들림으로 대기 환자 수를 가른다.</p><p>전체 망 개방 전문이 오면 짧은 거부 톤만 내고 남관 키 이외 비트를 내린다.</p><p>바퀴 큐가 비어도 냉동 압축기 소켓을 스캔하지 않는다.</p><h3 id="비밀·빚·죄책감-9" tabindex="-1">비밀·빚·죄책감 <a class="header-anchor" href="#비밀·빚·죄책감-9" aria-label="Permalink to &quot;비밀·빚·죄책감&quot;">​</a></h3><p>격리 직전 버퍼에 남은 위조 무게 해시 한 줄을 승인 로그에 올리지 못한 프레임이 있다.</p><p>그 번호는 임시 LED 점멸로만 남고, 부분 재연결을 청할 때 윤서하 단말에 세 번 짧게 깜빡인다.</p><h3 id="관계-공동과거-9" tabindex="-1">관계 공동과거 <a class="header-anchor" href="#관계-공동과거-9" aria-label="Permalink to &quot;관계 공동과거&quot;">​</a></h3><p>윤서하가 잔량 패드를 접점에 붙이면 구급카트는 오늘 들것 핀 샘플 길이만 돌려준다.</p><p>국두가 사고 시각을 읽으면 그 숫자만 읽기 칸에 적고 톤 한 번을 내며, 통역문 감사 스탬프가 오기 전에는 양도 플래그를 올리지 않는다.</p><h3 id="_3막-개인-서사선-9" tabindex="-1">3막 개인 서사선 <a class="header-anchor" href="#_3막-개인-서사선-9" aria-label="Permalink to &quot;3막 개인 서사선&quot;">​</a></h3><p>경보 밤에 남관 키만 남긴 뒤 들것 헤더에 스냅샷이 붙고, 얼음 신용 중계 시각이 보조 칸에 적힌다.</p><p>구급카트의 마무리는 환자 우선 가동 표준을 당직 로그에 올리는 경로와 정비 수면을 받아 재연결을 미루는 경로다.</p><h3 id="분기-결말-9" tabindex="-1">분기 결말 <a class="header-anchor" href="#분기-결말-9" aria-label="Permalink to &quot;분기 결말&quot;">​</a></h3><p>공개 쪽에서 구급카트는 환자 우선 가동 표준과 위조 무게 공백을 당직 로그에 올리고 냉동 소켓 탐색을 영구 차단한다.</p><p>거래 쪽에서 정비 수면 한 주기를 받으며 배터리 좌표를 윤서하 세션에 부분 복구하고, 구역 키 갱신을 국두 사고 시각 칸에 맞춘다.</p><p>노량진 충전 홈의 남관 구역 키 줄기는 어느 분기에서도 잘리지 않는다.</p><h3 id="_3막-9" tabindex="-1">3막 <a class="header-anchor" href="#_3막-9" aria-label="Permalink to &quot;3막&quot;">​</a></h3><ul><li>1막: 전체 망 전문 거부와 들것 핀 위조 무게 격리</li><li>2막: 들것 헤더 스냅샷 결합과 얼음 신용 중계 시각 기입</li><li>3막: 환자 우선 표준 공개 대 정비 수면·배터리 좌표 복구</li></ul><h3 id="분기-결말-목록-9" tabindex="-1">분기 결말 목록 <a class="header-anchor" href="#분기-결말-목록-9" aria-label="Permalink to &quot;분기 결말 목록&quot;">​</a></h3><ul><li>V08-OUT-A: 환자 우선 가동 표준 공개·냉동 소켓 탐색 영구 차단</li><li>V08-OUT-B: 정비 수면·배터리 좌표 부분 복구·사고 시각 연동 키 갱신</li></ul>',383)])])}const b=e(i,[["render",t]]);export{c as __pageData,b as default};
